scripts.pr-context:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'pr-context',
  description:
    'Resolve which PR to review and fetch its metadata + unified diff. Stamps {number, title, headRef, baseRef, diffChars} so the next step has the anchor.',
  inputs: {
    number: {
      type: 'number',
      description: 'PR number to review. Omit to pick the open PR matching the current branch.',
      integer: true,
    },
  },
  outputs: {
    number: { type: 'number', description: 'Resolved PR number.' },
    title: { type: 'string', description: 'PR title.' },
    headRef: { type: 'string', description: 'PR head branch.' },
    baseRef: { type: 'string', description: 'PR base branch.' },
    url: { type: 'string', description: 'PR URL.' },
    diffChars: { type: 'number', description: 'Length of the fetched diff body in chars.' },
  },
  requires: ['network'],
});

interface PrSummary {
  number: number;
  title: string;
  author: string;
  headRef: string;
  baseRef: string;
  draft: boolean;
  updatedAt: string;
  url: string;
}

async function resolvePr(input: { number?: number }): Promise<PrSummary> {
  if (input.number) {
    const view = await gezel.mcp.call('github_pr_view', { number: input.number });
    if (typeof view !== 'string') throw new Error('github_pr_view returned an unexpected shape');
    const headLine = view.split('\n')[0] ?? '';
    const titleMatch = /^#(\d+) — (.+)$/.exec(headLine);
    if (!titleMatch) throw new Error(`could not parse github_pr_view output: ${headLine}`);
    return {
      number: Number(titleMatch[1]),
      title: titleMatch[2]!,
      author: '?',
      headRef: '',
      baseRef: '',
      draft: false,
      updatedAt: '',
      url: '',
    };
  }
  const listing = await gezel.mcp.call('github_pr_list', {});
  if (typeof listing !== 'string') throw new Error('github_pr_list returned an unexpected shape');
  const firstLine = listing.split('\n\n')[0] ?? '';
  const m = /^#(\d+) — (.+?) \((.+?), (.+?) → (.+?)(?:, draft)?\)/.exec(firstLine);
  if (!m) {
    throw new Error(
      `couldn't pick a PR — github_pr_list returned no open PRs or unexpected shape:\n${listing.slice(0, 200)}`,
    );
  }
  return {
    number: Number(m[1]),
    title: m[2]!,
    author: m[3]!,
    headRef: m[4]!,
    baseRef: m[5]!,
    draft: firstLine.includes('draft'),
    updatedAt: '',
    url: '',
  };
}

async function main(): Promise<void> {
  const input = gezel.input as { number?: number };
  const pr = await resolvePr(input);
  gezel.log(`Resolved PR #${pr.number} — "${pr.title}"`);
  const diff = await gezel.mcp.call('github_pr_diff', { number: pr.number });
  const diffStr = typeof diff === 'string' ? diff : '';
  gezel.output({
    number: pr.number,
    title: pr.title,
    headRef: pr.headRef,
    baseRef: pr.baseRef,
    url: pr.url,
    diffChars: diffStr.length,
  });
}

await main();

scripts.diff-scan:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'diff-scan',
  description:
    'Pattern-scan a PR diff for common safety/quality issues — SQL concat, unguarded any, console.log leftovers, secret-shaped strings, missing tests. Stamps {findings[], clean: boolean}.',
  inputs: {
    number: { type: 'number', description: 'PR number.', integer: true, required: true },
  },
  outputs: {
    findings: {
      type: 'array',
      description: 'Issues found, each with file, line, severity, kind, snippet.',
      itemType: 'object',
    },
    clean: { type: 'boolean', description: 'True iff no must-fix or should-fix findings.' },
  },
  requires: ['network'],
});

type Severity = 'must-fix' | 'should-fix' | 'nit';

interface Finding {
  file: string;
  line: number;
  severity: Severity;
  kind: string;
  snippet: string;
}

const RULES: Array<{
  kind: string;
  severity: Severity;
  regex: RegExp;
  description: string;
}> = [
  {
    kind: 'sql-concat',
    severity: 'must-fix',
    regex: /(query|sql|execute)\s*\(\s*["'`][^"'`]*\$\{|\b\+\s*req\.(query|body|params)\./i,
    description: 'String-concatenated SQL or user input flowing into a query.',
  },
  {
    kind: 'console-leftover',
    severity: 'nit',
    regex: /^\+.*\bconsole\.(log|warn|error|debug)\b/,
    description: 'console.* call left in production code.',
  },
  {
    kind: 'secret-shape',
    severity: 'must-fix',
    regex: /(api[_-]?key|secret|token|password)\s*[:=]\s*["'][A-Za-z0-9+/=_-]{16,}["']/i,
    description: 'String-literal that looks like a hard-coded credential.',
  },
  {
    kind: 'unguarded-any',
    severity: 'should-fix',
    regex: /:\s*any\b(?!\[)|<any>/,
    description: "Explicit `any` — confirm it's the minimum-friction choice, not a bypass.",
  },
  {
    kind: 'todo-marker',
    severity: 'nit',
    regex: /^\+.*\b(TODO|FIXME|XXX)\b/,
    description: 'TODO/FIXME left behind. Either resolve or open an issue.',
  },
  {
    kind: 'force-unwrap',
    severity: 'should-fix',
    regex: /^\+.*![.\s]/,
    description: 'Non-null assertion (`!`) — confirm the invariant or add a guard.',
  },
];

interface ParsedHunk {
  file: string;
  baseLine: number;
  text: string;
}

function* iterHunks(diff: string): Generator<ParsedHunk> {
  let currentFile = '';
  let inHunk = false;
  let baseLine = 0;
  const lines = diff.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const ln = lines[i]!;
    const fileMatch = /^\+\+\+ b\/(.+)$/.exec(ln);
    if (fileMatch) {
      currentFile = fileMatch[1]!;
      inHunk = false;
      continue;
    }
    const hunkMatch = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(ln);
    if (hunkMatch) {
      baseLine = Number(hunkMatch[1]);
      inHunk = true;
      continue;
    }
    if (!inHunk || !currentFile) continue;
    if (ln.startsWith('+') && !ln.startsWith('+++')) {
      yield { file: currentFile, baseLine, text: ln };
      baseLine++;
    } else if (!ln.startsWith('-')) {
      baseLine++;
    }
  }
}

async function main(): Promise<void> {
  const input = gezel.input as { number: number };
  const diff = await gezel.mcp.call('github_pr_diff', { number: input.number });
  if (typeof diff !== 'string') {
    throw new Error('github_pr_diff returned an unexpected shape');
  }
  const findings: Finding[] = [];
  for (const hunk of iterHunks(diff)) {
    for (const rule of RULES) {
      if (rule.regex.test(hunk.text)) {
        findings.push({
          file: hunk.file,
          line: hunk.baseLine,
          severity: rule.severity,
          kind: rule.kind,
          snippet: hunk.text.slice(1, 140),
        });
      }
    }
  }
  const blocking = findings.filter((f) => f.severity !== 'nit');
  gezel.log(`Scanned diff: ${findings.length} finding(s), ${blocking.length} blocking`);
  gezel.output({ findings, clean: blocking.length === 0 });
}

await main();

scripts.diff-gate:
import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'diff-gate',
  description:
    'Gate for the scan-diff phase: runs diff-scan and routes the review — a clean diff approves straight to the approve step; findings approve to raise-findings with the findings carried in the handoff.',
  kind: 'gate',
  outputs: {
    decision: { type: 'string', description: "'approve' (the scan itself succeeding is the bar)." },
    message: { type: 'string', description: 'One-line scan summary.' },
  },
  // Nested script execution inherits diff-scan's needs; the scan itself
  // declares 'network'.
  requires: ['network'],
});

interface ScanOutput {
  clean: boolean;
  findings?: Array<{ severity?: string; note?: string; file?: string }>;
}

// Gate-as-router: the step "completing" means the scan ran — the JUDGMENT
// here is which branch the review takes next, expressed as approve+goto.
// A scan failure rejects (fail-closed) so a broken scan never silently
// approves a PR.
const result = await gezel.script.run<ScanOutput>('diff-scan');
if (result.status !== 'ok' || !result.output) {
  gezel.output({
    decision: 'reject',
    message: `diff-scan failed (${result.error ?? 'no output'}) — fix the scan inputs (is the PR context loaded?) and advance again.`,
  });
} else if (result.output.clean) {
  gezel.output({
    decision: 'approve',
    goto: 'approve',
    message: 'diff-scan found no must-fix or should-fix issues',
    handoff: { message: 'Automated diff scan came back clean — proceed to approval.' },
  });
} else {
  const findings = result.output.findings ?? [];
  const top = findings
    .slice(0, 5)
    .map((f) => `- [${f.severity ?? 'note'}] ${f.file ?? ''} ${f.note ?? ''}`.trim())
    .join('\n');
  gezel.output({
    decision: 'approve',
    goto: 'raise-findings',
    message: `diff-scan flagged ${findings.length} finding(s)`,
    handoff: {
      message: `Automated diff scan flagged ${findings.length} finding(s) to raise on the PR:\n${top}`,
      params: { findingCount: findings.length },
    },
  });
}
